# Generated by lang/generate.py: float values given by their bits, each
# printed by repr, str, format specifications and float.hex.
import struct


def f(bits):
    return struct.unpack("<d", bits.to_bytes(8, "little"))[0]


bits = [
    0x0000000000000000, 0x8000000000000000, 0x3ff0000000000000,
    0xbff0000000000000, 0x3fe0000000000000, 0x3fb999999999999a,
    0x3fc999999999999a, 0x3fd3333333333333, 0x3fd3333333333334,
    0x3fd5555555555555, 0x3fe5555555555555, 0x3e7ad7f29abcaf48,
    0x3eb0c6f7a0b5ed8d, 0x3ee4f8b588e368f1, 0x3f1a36e2eb1c432d,
    0x3f50624dd2f1a9fc, 0x3f5437c5692b3cc5, 0x405edd2f1a9fbe77,
    0x430c6bf526340000, 0x4341c37937e08000, 0x4376345785d8a000,
    0x4415af1d78b58c40, 0x444b1ae4d6e2ef50, 0x4480f0cf064dd592,
    0x44b52d02c7e14af6, 0x4340000000000000, 0x4340000000000001,
    0x43e0000000000000, 0x43f0000000000000, 0x4340000000000000,
    0x437b69b4ba630f35, 0x4011666666666666, 0x4005666666666666,
    0x3ff0147ae147ae14, 0x3fc0000000000000, 0x0000000000000001,
    0x0000000000000003, 0x000fffffffffffff, 0x0010000000000000,
    0x7fefffffffffffff, 0xffefffffffffffff, 0x7fe1ccf385ebc8a0,
    0x000730d67819e8d2, 0x7ff0000000000000, 0xfff0000000000000,
    0x7ff8000000000000,
]
for b in bits:
    x = f(b)
    print(repr(x), str(x), format(x, "g"), format(x, ".17g"), format(x, "e"), format(x, ".3f"), x.hex(), x.is_integer())
